import Foundation
import Testing
@testable import XTouchCompactCore

/// Every row is generated by the real host state machine; time is a deterministic input label.
private struct BehaviorTrace {
    var session = try! CompactSession(map: FactoryStandardMap(), lightProtocol: .manual)
    var mock = try! MockXTouchCompact(map: FactoryStandardMap(), lightProtocol: .manual)
    var rows: [[String: Any]] = []

    mutating func step(_ operation: String, raw: [MIDIMessage] = [], fails: Bool = false,
                       run: (inout CompactSession) throws -> [MIDIMessage]) throws
    {
        let before = session.parameters.values
        let pendingBefore = (1 ... 9).filter { session.state.isMotorPending($0) }
        let output = try run(&session)
        let permitted = session.filterFeedbackForDelivery(output)
        if fails {
            session.invalidateTransportFeedback()
        } else {
            mock.receive(permitted)
        }
        var changes: [String: Double] = [:]
        for (key, value) in session.parameters.values where before[key] != value {
            changes[key] = value
        }
        let pending = (1 ... 9).filter { session.state.isMotorPending($0) }
        let cancelled = session.state.layerMismatch ? pendingBefore.filter { !pending.contains($0) } : []
        rows.append([
            "input": ["operation": operation, "raw_messages": raw.map(\.midi1Bytes),
                      "hardware_context": raw.first.flatMap { session.state.map.decode($0)?.layer.rawValue } as Any? ?? NSNull(),
                      "injected_time": Double(rows.count) / 10],
            "result": ["accepted": true, "rejection_reason": NSNull(), "parameter_changes": changes, "action_count": 0],
            "output": ["sent": fails ? [] : permitted.map(\.midi1Bytes),
                       "failed": fails ? permitted.map(\.midi1Bytes) : [],
                       "deferred": pending.map { ["control": "fader.\($0)", "reason": "touch"] },
                       "suppressed": output.filter { !permitted.contains($0) }.map { ["message": $0.midi1Bytes, "reason": "delivery_safety_gate"] },
                       "cancelled": cancelled.map { ["control": "fader.\($0)", "reason": "layer_mismatch"] }],
            "observation": ["host_layer": session.state.layer.rawValue,
                            "observed_layer": session.state.observedLayer?.rawValue as Any? ?? NSNull(),
                            "layer_mismatch": session.state.layerMismatch,
                            "fader_1_observed": session.state.observedFader(1).map { Int($0) } as Any? ?? NSNull(),
                            "fader_1_observation_current": NSNull(), "last_sent_motor": NSNull(),
                            "touched": (1 ... 9).filter { session.state.isTouched($0) }, "pending_motor": pending],
        ])
    }

    mutating func input(_ message: MIDIMessage) throws {
        try step("receive", raw: [message]) { try $0.receive([message]).feedback }
    }
}

@Test func mockBehaviorTracesMatchCheckedInBytes() throws {
    let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("Fixtures/BehaviorTraces")
    var traces: [String: BehaviorTrace] = [:]
    let touch = MIDIMessage.controlChange(channel: 0, number: 101, value: 127)
    let release = MIDIMessage.controlChange(channel: 0, number: 101, value: 0)
    var held = BehaviorTrace()
    try held.input(touch)
    try held.step("set_parameter_80") { try $0.setParameter("a.Fader.1", value: 80) }
    traces["01-touch-defers-write"] = held
    try held.input(release)
    traces["02-release-reconciles"] = held
    var cross = BehaviorTrace()
    try cross.input(touch)
    try cross.step("set_parameter_80") { try $0.setParameter("a.Fader.1", value: 80) }
    try cross.input(.controlChange(channel: 0, number: 37, value: 20))
    try cross.input(release)
    traces["03-cross-layer-release"] = cross
    var layer = BehaviorTrace()
    try layer.input(.controlChange(channel: 0, number: 107, value: 127))
    do {
        try layer.session.state.validateLayerAssertion()
        Issue.record("Touched layer assertion was accepted")
    } catch CompactError.fadersTouched {
        try layer.step("request_layer_b") { _ in [] }
        layer.rows[layer.rows.count - 1]["result"] = ["accepted": false, "rejection_reason": "fadersTouched", "parameter_changes": [:], "action_count": 0]
        layer.rows[layer.rows.count - 1]["output"] = ["sent": [], "deferred": [], "suppressed": [["category": "mechanism_motion", "reason": "fadersTouched", "affected_controls": Array(1 ... 9)]]]
    }
    traces["04-touched-layer-refused"] = layer
    var changed = BehaviorTrace()
    try changed.input(.controlChange(channel: 0, number: 1, value: 20))
    try changed.step("select_layer_b") { try $0.selectLayer(.b) }
    traces["05-layer-invalidates-observation"] = changed
    var failure = BehaviorTrace()
    try failure.step("failed_motor_write", fails: true) { try $0.setFader(1, value: 80) }
    try failure.step("retry_same_desired_value") { try $0.setFader(1, value: 80) }
    traces["06-send-failure-cache"] = failure
    var ring = BehaviorTrace()
    try ring.step("set_ring_value") { try $0.setDisplayRing(1, value: 64) }
    // Exercise the actual style redraw primitive (session exposes no style API).
    var state = ring.session.state
    let styleOutput = try state.setRingStyle(1, style: .pan)
    try ring.step("style_redraw_and_same_value") { _ in styleOutput }
    let sameValue = try state.setRing(1, display: .position(CompactSession.ringSegment(for: 64)))
    #expect(styleOutput == [.controlChange(channel: 0, number: 10, value: 1), .controlChange(channel: 0, number: 26, value: 7)])
    #expect(sameValue.isEmpty) // Style command already reasserted the desired value.
    try ring.step("same_ring_value_after_redraw") { _ in sameValue }
    traces["07-ring-style-redraw"] = ring
    var linked = BehaviorTrace()
    var config = SurfaceConfiguration.neutral
    config.assignments.removeAll { $0.control == .fader(2) && $0.layer == .a }
    config.assignments.append(.init(control: .fader(2), layer: .a, action: .parameter("a.Fader.1")))
    _ = try linked.session.loadConfiguration(config)
    try linked.input(touch)
    try linked.step("write_shared_parameter") { try $0.setParameter("a.Fader.1", value: 80) }
    traces["08-shared-parameter-touch"] = linked
    for name in traces.keys.sorted() {
        let document: [String: Any] = try ["schema_version": 1, "scenario": name, "source": "mock", "steps": #require(traces[name]?.rows)]
        let data = try JSONSerialization.data(withJSONObject: document, options: [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]) + Data([10])
        let path = root.appendingPathComponent(name + ".json")
        if ProcessInfo.processInfo.environment["UPDATE_BEHAVIOR_TRACES"] == "1" {
            try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
            try data.write(to: path)
        }
        #expect(try Data(contentsOf: path) == data, "Trace bytes differ: \(name)")
    }
}
